1	#!/usr/bin/env node
2	/**
3	 * ACTUAL PARTIAL WorldSave / Continue TEST — run-local to
4	 * 2026-09-05-after-the-hearth, bounded to ONE question:
5	 *
6	 *   Does a REAL, physically earned, UNFINISHED ch13 survey drawing survive the
7	 *   shipped save -> Continue lifecycle, and can a NEW signed action then be
8	 *   performed and accepted on the restored state?
9	 *
10	 * WHAT THIS IS NOT
11	 * ----------------
12	 *   - not a chapter verification, not a movie journey, not a cold-run measure;
13	 *   - no teleport, no progress/milestone setter, no direct predicate call, no
14	 *     hand-constructed save payload, no relaxed arrival/route rule;
15	 *   - the movie rail is used ONLY as the shipped way of reaching the drawing
16	 *     state (exactly as capture world-final/survey-1 did). Where the rail
17	 *     stalls, ORDINARY shipped movement keys are pressed. Any such key input is
18	 *     labelled `scripted-input` and NEVER counted as zero-rescue movie success.
19	 *
20	 * LIFECYCLE UNDER TEST (all shipped code paths, no fixtures):
21	 *   1. `?story=ch13-survey&movie=1` — the survey deep link (a PREREQUISITE
22	 *      FIXTURE: it seeds ch13FaultReviewed/ch13ReturnChosen milestones; it is
23	 *      not earned play and is labelled as such).
24	 *   2. Earn the partial recording with actual shipped movement/[F] inputs.
25	 *   3. Save through the shipped autosave-on-unload path (App.tsx `beforeunload`
26	 *      -> doSave(true) -> saveWorld -> serializeCommonGroundForWorld), fired by
27	 *      a same-tab navigation away from the game. The ACTUAL serialized
28	 *      localStorage bytes are copied out as evidence before the browser closes.
29	 *   4. Boot the menu with NO story deep link and press the real Continue button
30	 *      (LandingMenu -> beginStory -> storyEntryPoint). Browser storage is
31	 *      retained across the navigation; nothing is re-seeded.
32	 *   5. Compare restored route/identity/actor progress, check that no earned
33	 *      action replays into fresh AV history, then perform a NEW action (walk to
34	 *      E with ordinary keys, offer the span with [F]) and check its signed AV
35	 *      anchor is accepted.
36	 *
37	 * Everything is measured; nothing here decides acceptance.
38	 */
39	import { mkdirSync, writeFileSync, appendFileSync, readFileSync } from 'node:fs';
40	import { resolve, join } from 'node:path';
41	import { createHash } from 'node:crypto';
42	import process from 'node:process';
43	import { ART, CAPTURES, RUN_DIR, REPO_ROOT, MAIN } from '../lib/cgContract.mjs';
44	import { createOwnedSessionGuard, failureRecord } from '../lib/ownedSession.mjs';
45	import { assertFreshOutputDir, writeSourceSnapshot, snapshotRef } from '../lib/sourceSnapshot.mjs';
46	import { openParavoxia, waitReady, readState } from '../../../../../../main/tools/lib/evidence.mjs';
47	
48	// ------------------------------------------------------------------ args ---
49	const arg = (n, d = null) => {
50	  const i = process.argv.indexOf(`--${n}`);
51	  return i >= 0 && process.argv[i + 1] !== undefined && !process.argv[i + 1].startsWith('--')
52	    ? process.argv[i + 1] : d;
53	};
54	const outName = arg('out', 'run-1');
55	const minSamples = Number(arg('min-samples', '4'));
56	const earnBudgetMs = Number(arg('earn-ms', '120000'));
57	const walkBudgetMs = Number(arg('walk-ms', '90000'));
58	const outDir = resolve(CAPTURES, 'partial-continue', outName);
59	
60	// ------------------------------------------------------- self-test (no GPU) ---
61	// Exercises the pure decision helpers with no browser, no preview, no game.
62	const unit = (v) => { const m = Math.hypot(v[0], v[1]); return m < 1e-9 ? [0, 0] : [v[0] / m, v[1] / m]; };
63	const dot2 = (a, b) => a[0] * b[0] + a[1] * b[1];
64	const distXZ = (a, b) => Math.hypot(a[0] - b[0], a[2] - b[2]);
65	const dist3 = (a, b) => Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]);
66	/** Pick the ordinary movement key whose measured world direction best matches want. */
67	function chooseKey(dirs, want) {
68	  let best = null; let bestDot = -Infinity;
69	  for (const [k, d] of Object.entries(dirs)) {
70	    if (!d) continue;
71	    const s = dot2(d, want);
72	    if (s > bestDot) { bestDot = s; best = k; }
73	  }
74	  return { key: best, score: bestDot };
75	}
76	if (process.argv.includes('--self-test')) {
77	  const fail = (m) => { console.error(`[partial-continue self-test] FAIL ${m}`); process.exit(1); };
78	  const dirs = { KeyW: [-0.87, 0.49], KeyS: [0.87, -0.49], KeyA: [-0.49, -0.87], KeyD: [0.49, 0.87] };
79	  if (chooseKey(dirs, unit([-1, 0])).key !== 'KeyW') fail('west target should pick the measured westward key');
80	  if (chooseKey(dirs, unit([1, 0])).key !== 'KeyS') fail('east target should pick its opposite');
81	  if (chooseKey(dirs, unit([0.49, 0.87])).key !== 'KeyD') fail('exact key direction must win');
82	  if (Math.abs(distXZ([0, 0, 0], [3, 99, 4]) - 5) > 1e-9) fail('distXZ ignores the up axis');
83	  if (Math.abs(dist3([0, 0, 0], [0, 3, 4]) - 5) > 1e-9) fail('dist3 uses all three axes');
84	  const p = projectedProgress([0, 0, 0], [-1, 0, 0.5], [-10, 0, 0]);
85	  if (!(p.alongLeg > 0.9 && p.alongLeg < 1.1)) fail(`projected along-leg wrong: ${p.alongLeg}`);
86	  if (!(Math.abs(p.lateral - 0.5) < 1e-9)) fail(`lateral component wrong: ${p.lateral}`);
87	  const q = projectedProgress([0, 0, 0], [0, 0, 2], [-10, 0, 0]);
88	  if (Math.abs(q.alongLeg) > 1e-9) fail('a pure sidestep must project to zero along the intended leg');
89	  console.log('[partial-continue self-test] OK');
90	  process.exit(0);
91	}
92	
93	/**
94	 * Displacement resolved ALONG the intended leg vs LATERAL to it. Root's note:
95	 * a lateral sidestep alone does not prove the original direction was clear, so
96	 * collision discrimination reports both components, never just gross distance.
97	 */
98	function projectedProgress(from, moved, target) {
99	  const leg = unit([target[0] - from[0], target[2] - from[2]]);
100	  const d = [moved[0] - from[0], moved[2] - from[2]];
101	  const along = dot2(d, leg);
102	  const lateral = Math.hypot(d[0] - along * leg[0], d[1] - along * leg[1]);
103	  return { alongLeg: along, lateral, gross: Math.hypot(d[0], d[1]) };
104	}
105	
106	// ------------------------------------------------------------------ setup ---
107	assertFreshOutputDir(outDir, { what: 'partial-continue' });
108	mkdirSync(outDir, { recursive: true });
109	const tracePath = join(outDir, 'trace.ndjson');
110	const t0 = Date.now();
111	const log = [];
112	const say = (m) => {
113	  const line = `${new Date().toISOString()} +${Date.now() - t0}ms ${m}`;
114	  console.log(`[pc] ${m}`);
115	  log.push(line);
116	};
117	const emit = (rec) => appendFileSync(tracePath, `${JSON.stringify({ atMs: Date.now() - t0, at: new Date().toISOString(), ...rec })}\n`);
118	const sha = (s) => createHash('sha256').update(s).digest('hex');
119	const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
120	
121	const own = JSON.parse(readFileSync(resolve(ART, 'preview-ownership.json'), 'utf8'));
122	if (own.state !== 'running') throw new Error(`root preview is not running (state=${own.state}); this probe never starts one`);
123	const previewRef = { url: own.url, stop() { /* ROOT owns this preview's lifetime */ } };
124	
125	const sourceManifest = writeSourceSnapshot({
126	  entryAbs: new URL(import.meta.url).pathname, outDir, repoRoot: REPO_ROOT,
127	  note: 'Exact probe + library bytes of the partial WorldSave/Continue test.'
128	});
129	
130	// ------------------------------------------------------- page-side readers ---
131	const cgSnap = (page) => page.evaluate(() => {
132	  const s = window.__paravoxiaCommonGround?.snapshot?.();
133	  if (!s) return null;
134	  return {
135	    beat: s.beat, bodyCentre: s.bodyCentre, bodyPose: s.bodyPose, up: s.up,
136	    supported: s.supported, worldBound: s.worldBound, rail: s.rail, railCursor: s.railCursor,
137	    score: s.score, pendingAnchors: s.pendingAnchors,
138	    anchors: s.diagnostic?.anchors ?? null,
139	    holdReason: s.diagnostic?.holdReason ?? null,
140	    worker: s.diagnostic?.worker ?? null,
141	    survey: s.diagnostic?.survey ?? null,
142	    common: s.diagnostic?.common ?? null
143	  };
144	});
145	
146	/** Everything the shipped persistence layer actually wrote, verbatim. */
147	const readStorage = (page) => page.evaluate(() => {
148	  const out = { keys: [], world: [], global: null, globalKey: null };
149	  for (let i = 0; i < localStorage.length; i++) {
150	    const k = localStorage.key(i);
151	    const v = localStorage.getItem(k) ?? '';
152	    out.keys.push({ key: k, bytes: v.length });
153	    if (/\.world\.[^.]+$/.test(k)) out.world.push({ key: k, raw: v });
154	    if (/\.global$/.test(k) || /global/.test(k)) { out.globalKey = k; out.global = v; }
155	  }
156	  return out;
157	});
158	
159	const uiProbe = (page) => page.evaluate(() => {
160	  const cta = document.querySelector('button[aria-describedby="landing-story-subtitle"]');
161	  const sub = document.getElementById('landing-story-subtitle');
162	  const pause = document.querySelector('button[aria-label="Pause"], button[aria-label="Pause and open star map"]');
163	  const hud = document.querySelector('[data-story-guidance-hud]');
164	  const txt = (el) => (el ? el.innerText.replace(/\s+/g, ' ').trim() : null);
165	  return {
166	    title: document.title,
167	    landingCta: txt(cta), landingSubtitle: txt(sub), landingMenuPresent: !!cta,
168	    pauseButton: pause ? (pause.getAttribute('aria-label')) : null,
169	    hudPresent: !!hud,
170	    objectiveId: hud?.getAttribute('data-objective-id') ?? null,
171	    markerLabel: hud?.getAttribute('data-objective-marker-label') ?? null,
172	    hudText: txt(hud),
173	    buttons: [...document.querySelectorAll('button')].map((b) => txt(b)).filter(Boolean).slice(0, 40)
174	  };
175	});
176	
177	const shot = async (page, name) => {
178	  const p = join(outDir, name);
179	  await page.screenshot({ path: p });
180	  return { file: name, sha256: sha(readFileSync(p)) };
181	};
182	
183	/**
184	 * ORDINARY SHIPPED MOVEMENT, closed loop.
185	 *
186	 * Calibrates each WASD key by pressing it briefly and measuring the REAL world
187	 * displacement of the body, then walks toward `target` in short bursts, always
188	 * recording the displacement resolved ALONG the intended leg and LATERAL to it
189	 * (a sidestep is not proof the intended direction was clear).
190	 *
191	 * This is scripted input on the shipped controls. It is never a teleport, never
192	 * a grant, never a rescue, and no movie run is called successful because of it.
193	 */
194	async function walkTowards(page, target, {
195	  budgetMs = 90000, arriveUnits = 1.2, stopWhen = null, minDistToTarget = 0, calibrate = true, dirs = {}, say: log = () => {}
196	} = {}) {
197	  const journey = [];
198	  const keys = ['KeyW', 'KeyS', 'KeyA', 'KeyD'];
199	  for (const k of keys) if (!(k in dirs)) dirs[k] = null;
200	  if (calibrate) {
201	    for (const key of keys) {
202	      const b = (await cgSnap(page))?.bodyCentre;
203	      await page.keyboard.down(key); await sleep(450); await page.keyboard.up(key); await sleep(350);
204	      const a = (await cgSnap(page))?.bodyCentre;
205	      const d = [a[0] - b[0], a[2] - b[2]];
206	      dirs[key] = Math.hypot(...d) > 0.05 ? unit(d) : null;
207	      journey.push({ step: 'calibrate', key, from: b, to: a, moved: Math.hypot(...d), dir: dirs[key] });
208	      log(`calibrate ${key}: moved ${Math.hypot(...d).toFixed(3)} dir=${JSON.stringify(dirs[key])}`);
209	    }
210	  }
211	  const t = Date.now();
212	  let cur = await cgSnap(page);
213	  let bursts = 0; let stopReason = 'budget-exhausted';
214	  while (Date.now() - t < budgetMs) {
215	    if (stopWhen && await stopWhen(cur)) { stopReason = 'stop-condition'; break; }
216	    const dTo = distXZ(cur.bodyCentre, target);
217	    if (dTo <= arriveUnits) { stopReason = 'arrived'; break; }
218	    if (minDistToTarget && dTo <= minDistToTarget) { stopReason = 'hold-off-distance'; break; }
219	    const want = unit([target[0] - cur.bodyCentre[0], target[2] - cur.bodyCentre[2]]);
220	    const pick = chooseKey(dirs, want);
221	    if (!pick.key) { stopReason = 'no-key-produced-displacement'; break; }
222	    const b = cur.bodyCentre;
223	    await page.keyboard.down(pick.key); await sleep(400); await page.keyboard.up(pick.key); await sleep(220);
224	    cur = await cgSnap(page);
225	    const proj = projectedProgress(b, cur.bodyCentre, target);
226	    const moved = [cur.bodyCentre[0] - b[0], cur.bodyCentre[2] - b[2]];
227	    if (Math.hypot(...moved) > 0.05) dirs[pick.key] = unit(moved);
228	    bursts++;
229	    journey.push({ step: 'walk', burst: bursts, key: pick.key, from: b, to: cur.bodyCentre,
230	      distToTarget: distXZ(cur.bodyCentre, target), alongLeg: proj.alongLeg, lateral: proj.lateral,
231	      gross: proj.gross, supported: cur.supported, samples: cur.survey?.samples, walked: cur.survey?.walkedUnits });
232	    if (bursts % 8 === 0) log(`burst ${bursts}: body=${cur.bodyCentre.map((n) => n.toFixed(2))} distToTarget=${distXZ(cur.bodyCentre, target).toFixed(2)} samples=${cur.survey?.samples}`);
233	  }
234	  return { journey, dirs, bursts, stopReason, ms: Date.now() - t, final: cur,
235	    label: 'scripted-input journey with ORDINARY shipped movement keys (never a movie zero-rescue claim)' };
236	}
237	
238	const avOf = (st) => ({
239	  beat: st?.av?.beat ?? null,
240	  active: st?.av?.active ?? null,
241	  history: st?.av?.activationHistoryAnchorIds ?? st?.av?.history ?? null,
242	  ledger: st?.av?.anchorLedger ?? null
243	});
244	
245	// ------------------------------------------------------------------- main ---
246	const guard = createOwnedSessionGuard({ log: say, label: 'partial-continue' });
247	const report = {
248	  schema: 'paravoxia.verifier.partialContinue.v1',
249	  probe: 'partial-continue-probe.mjs',
250	  startedAt: new Date(t0).toISOString(),
251	  question: 'Does an actual unfinished ch13 survey drawing survive the shipped save -> Continue lifecycle, and is a NEW signed action then accepted?',
252	  isAcceptance: false,
253	  isChapterVerification: false,
254	  preview: { url: own.url, bundlePath: own.bundlePath, bundleSha256: own.bundleSha256, indexSha256: own.indexSha256, sourceManifestSha256: own.sourceManifestSha256, ownedBy: own.owner },
255	  probeSource: snapshotRef(sourceManifest),
256	  prerequisiteFixtures: [], actualInteractions: [], phases: {}, findings: []
257	};
258	
259	try {
260	  // ---------------------------------------------------------- PHASE 1: earn ---
261	  say('PHASE 1 — boot the shipped survey entry and earn a real partial drawing');
262	  const session = guard.adopt(await openParavoxia({
263	    url: '?story=ch13-survey&journeyprobe=1&debug=1&movie=1',
264	    preview: previewRef, build: false, viewport: { width: 1280, height: 720 }, log: say
265	  }));
266	  const page = session.page;
267	  report.renderer = session.renderer;
268	  report.headed = session.headed;
269	  report.entryUrl = session.url;
270	  report.prerequisiteFixtures.push({
271	    what: 'story deep link ?story=ch13-survey',
272	    effect: 'seedForBeat marks story:ch13-fault-reviewed and story:ch13-return-chosen and clears voxel edits/pose for the story worlds (storyState.ts seedForBeat). NOT earned play.',
273	    label: 'prerequisite-fixture'
274	  });
275	  report.prerequisiteFixtures.push({
276	    what: 'movie=1 rail',
277	    effect: 'The shipped ch13-survey rail drives the same keys/verbs a player uses. Used only to reach the drawing state, exactly as capture world-final/survey-1 did.',
278	    label: 'scripted-input-journey'
279	  });
280	  say(`renderer=${session.renderer} headed=${session.headed}`);
281	  await waitReady(page, { timeoutMs: 120000 });
282	
283	  const earn0 = Date.now();
284	  let cg = null; let st = null;
285	  let lastGrowthAt = Date.now(); let lastSamples = -1;
286	  while (Date.now() - earn0 < earnBudgetMs) {
287	    cg = await cgSnap(page);
288	    st = await readState(page);
289	    emit({ phase: 'earn', cg, beat: st?.beat, objectiveId: st?.objectiveId, av: avOf(st) });
290	    const n = cg?.survey?.samples ?? -1;
291	    if (n !== lastSamples) { lastSamples = n; lastGrowthAt = Date.now(); }
292	    if (cg?.survey?.phase === 'drawing' && n >= minSamples) break;
293	    // Do not re-run the already-established 150 s stall: once the drawing is
294	    // open and the rail has stopped growing it, hand over to ordinary input.
295	    if (cg?.survey?.phase === 'drawing' && Date.now() - lastGrowthAt > 15000) {
296	      say(`movie rail has not grown the drawing for 15 s at ${n} samples — treating as the known rail stall`);
297	      break;
298	    }
299	    await sleep(750);
300	  }
301	  const railMs = Date.now() - earn0;
302	  const railState = cg;
303	  say(`movie rail alone after ${railMs}ms: phase=${cg?.survey?.phase} samples=${cg?.survey?.samples} walked=${cg?.survey?.walkedUnits} body=${JSON.stringify(cg?.bodyCentre)}`);
304	  const shotRail = await shot(page, '0000-movie-rail-state.png');
305	
306	  // The rail stall (VF4-SURVEY-STALL-1) is already an established observation.
307	  // It does not block SAVING a partial drawing: ordinary shipped keys grow the
308	  // real recording. Held well short of E so no offer can fire in this phase.
309	  let earnWalk = null;
310	  if (cg?.survey?.phase === 'drawing' && (cg.survey.samples ?? 0) < minSamples) {
311	    say(`rail produced only ${cg.survey.samples} samples; growing the drawing with ORDINARY movement keys (scripted input, not a movie success)`);
312	    earnWalk = await walkTowards(page, [-42, 51.05, 12], {
313	      budgetMs: 60000, arriveUnits: 1.2, minDistToTarget: 8, say,
314	      stopWhen: async (s) => (s?.survey?.samples ?? 0) >= minSamples
315	    });
316	    cg = await cgSnap(page);
317	    say(`after ${earnWalk.bursts} ordinary bursts (${earnWalk.stopReason}): samples=${cg?.survey?.samples} walked=${cg?.survey?.walkedUnits} body=${JSON.stringify(cg?.bodyCentre)}`);
318	  }
319	  const earnMs = Date.now() - earn0;
320	  const shotEarned = await shot(page, '0001-earned-partial-drawing.png');
321	  const earnedState = await readState(page);
322	  const earnedUi = await uiProbe(page);
323	  report.phases.earn = {
324	    lane: 'movie+ordinary-keys', earnMs, cg, ui: earnedUi, frame: shotEarned,
325	    railOnly: { ms: railMs, state: railState, frame: shotRail,
326	      note: 'The movie rail alone reached this state and then stalled; it is NOT reported as a zero-rescue movie success.' },
327	    ordinaryKeyGrowth: earnWalk,
328	    milestones: earnedState?.milestones ?? null,
329	    av: avOf(earnedState),
330	    objectiveId: earnedState?.objectiveId ?? null,
331	    markerLabel: earnedState?.markerLabel ?? null,
332	    hudText: earnedState?.hudText ?? null,
333	    system: earnedState?.system ?? null,
334	    routeTestedMilestonePresent: (earnedState?.milestones ?? []).includes('story:ch13-route-tested'),
335	    reached: cg?.survey?.phase === 'drawing' && (cg?.survey?.samples ?? 0) >= minSamples
336	  };
337	  if (!report.phases.earn.reached) {
338	    report.findings.push({ id: 'PC-EARN-BLOCKED', detail: `did not reach a >=${minSamples}-sample drawing within ${earnBudgetMs}ms`, state: cg });
339	    throw new Error('partial drawing not earned — see report.findings PC-EARN-BLOCKED');
340	  }
341	  if (report.phases.earn.routeTestedMilestonePresent) {
342	    report.findings.push({ id: 'PC-CHECKPOINT-IMPURE', detail: 'story:ch13-route-tested already present at the checkpoint; this is no longer a PARTIAL save' });
343	  }
344	
345	  // ------------------------------------------------- PHASE 2: shipped save ---
346	  say('PHASE 2 — save through the shipped autosave lifecycle (beforeunload -> doSave)');
347	  const preSaveStorage = await readStorage(page);
348	  report.phases.save = { beforeNavigation: { keys: preSaveStorage.keys, worldKeys: preSaveStorage.world.map((w) => w.key) } };
349	  for (const w of preSaveStorage.world) {
350	    writeFileSync(join(outDir, `worldsave-presave-${w.key.replace(/[^\w.-]/g, '_')}.json`), w.raw);
351	  }
352	
353	  const menuUrl = new URL('?journeyprobe=1&debug=1', own.url).toString();
354	  say(`navigating same tab to ${menuUrl} — this fires the shipped beforeunload autosave and RETAINS localStorage`);
355	  await page.goto(menuUrl, { waitUntil: 'load', timeout: 180000 });
356	  report.actualInteractions.push({ what: 'same-tab navigation away from the running game', shippedPath: 'App.tsx beforeunload -> doSave(true) -> saveWorld/savePlayerPose/saveGlobal', label: 'actual-shipped-save' });
357	
358	  const savedStorage = await readStorage(page);
359	  const saved = savedStorage.world.map((w) => {
360	    let parsed = null; try { parsed = JSON.parse(w.raw); } catch { /* keep raw */ }
361	    const file = `worldsave-${w.key.replace(/[^\w.-]/g, '_')}.json`;
362	    writeFileSync(join(outDir, file), w.raw);
363	    const cgBlob = parsed?.commonGround ?? null;
364	    return {
365	      key: w.key, bytes: w.raw.length, sha256: sha(w.raw), file,
366	      worldId: parsed?.worldId ?? null, seed: parsed?.seed ?? null,
367	      hasCommonGround: cgBlob != null,
368	      commonGroundSha256: cgBlob ? sha(JSON.stringify(cgBlob)) : null,
369	      commonGround: cgBlob
370	    };
371	  });
372	  if (savedStorage.global) writeFileSync(join(outDir, 'globalsave.json'), savedStorage.global);
373	  let globalParsed = null; try { globalParsed = JSON.parse(savedStorage.global ?? 'null'); } catch { /* ignore */ }
374	  report.phases.save.actualWorldSaves = saved.map(({ commonGround, ...rest }) => rest);
375	  report.phases.save.savedCommonGround = saved.find((s) => s.hasCommonGround)?.commonGround ?? null;
376	  report.phases.save.globalSave = globalParsed
377	    ? { key: savedStorage.globalKey, sha256: sha(savedStorage.global), milestones: globalParsed.milestones ?? null, lastPlanetWorldId: globalParsed.lastPlanetWorldId ?? null }
378	    : null;
379	  report.phases.save.routeTestedMilestoneInSave = (globalParsed?.milestones ?? []).includes('story:ch13-route-tested');
380	  say(`saved world blobs: ${JSON.stringify(report.phases.save.actualWorldSaves)}`);
381	  if (!saved.some((s) => s.hasCommonGround)) {
382	    report.findings.push({ id: 'PC-SAVE-NO-COMMONGROUND', detail: 'the shipped save wrote no commonGround blob for any world key after an earned partial drawing' });
383	  }
384	
385	  // ----------------------------------------------- PHASE 3: real Continue ---
386	  say('PHASE 3 — operate the real Continue UI (no deep link, storage retained)');
387	  // The menu boot has no story runtime yet, so `waitReady`'s beat/`__game`
388	  // predicate does not apply here: wait for the actual landing CTA element.
389	  await page.waitForSelector('button[aria-describedby="landing-story-subtitle"]', { timeout: 120000 });
390	  await sleep(6000);
391	  const menuUi = await uiProbe(page);
