384	/**
385	 * Decide whether a browser may be launched AT ALL. Refuses on unreadiness, on a
386	 * verifier control hold, on a missing/foreign URL, on anything short of a proven
387	 * externally acquired exclusive lock, on an unbound source manifest and on an
388	 * unbound served build. Pure: callers pass the loaded files and the receipts.
389	 */
390	export function preflightDecision({
391	  ready = null, control = null, url = null, out = null,
392	  heavyLock = null, expectSourceManifestSha = null, liveSourceManifestSha = null,
393	  previewBinding = null, role = 'common-manual-focused'
394	} = {}) {
395	  const refusals = [];
396	  if (!ready || ready.ready !== true) refusals.push(`verification-ready.json ready=${ready ? String(ready.ready) : 'missing'}`);
397	  if (!control) refusals.push('verifier-control.json missing');
398	  else {
399	    if (control.action === 'hold') refusals.push(`verifier control action=hold (${String(control.instruction ?? '').slice(0, 120)})`);
400	    if (control.activeRole && control.activeRole !== role) refusals.push(`verifier control activeRole=${control.activeRole}, not ${role}`);
401	  }
402	  if (!url) refusals.push('--url is required (root-published canonical URL); no hardcoded port default exists');
403	  else if (!/^https?:\/\//.test(url)) refusals.push(`--url ${url} is not an http(s) URL`);
404	  if (!out) refusals.push('--out is required (unique run-local capture folder)');
405	  if (!heavyLock || heavyLock.owned !== true) {
406	    const why = (heavyLock?.problems ?? ['no lock receipt was produced']).join('; ');
407	    refusals.push(`exclusive shared heavy lock is not PROVABLY held by this process tree: ${why}`);
408	  }
409	  if (!expectSourceManifestSha) refusals.push('--expect-source-manifest is required and must be the NEW root-published manifest sha256');
410	  else if (liveSourceManifestSha && liveSourceManifestSha !== expectSourceManifestSha) {
411	    refusals.push(`source manifest sha mismatch: expected ${expectSourceManifestSha}, live ${liveSourceManifestSha}`);
412	  }
413	  if (!previewBinding || previewBinding.ok !== true) {
414	    const why = (previewBinding?.problems ?? ['served bytes were never bound to root preview ownership']).join('; ');
415	    refusals.push(`served build is not bound to root preview ownership: ${why}`);
416	  }
417	  return { launch: refusals.length === 0, refusals };
418	}
