      distToTarget: distXZ(cur.bodyCentre, target), alongLeg: proj.alongLeg, lateral: proj.lateral,
      gross: proj.gross, supported: cur.supported, samples: cur.survey?.samples, walked: cur.survey?.walkedUnits });
