  locationMode: st?.system?.locationMode ?? null,
  pos: st?.system?.pos ?? null,
  speed: st?.system?.speed ?? null,
  controlMode: st?.spaceFlight?.controlMode ?? null,
  phase: st?.spaceFlight?.phase ?? null
});

