  if (Math.abs(distXZ([0, 0, 0], [3, 99, 4]) - 5) > 1e-9) fail('distXZ ignores the up axis');
  if (Math.abs(dist3([0, 0, 0], [0, 3, 4]) - 5) > 1e-9) fail('dist3 uses all three axes');
