      firedAnchors: rCg?.anchors ?? null, pendingAnchors: rCg?.pendingAnchors ?? null });
    const ms = rSt?.milestones ?? [];
    const sig = `${rSt?.beat}|${rSt?.objectiveId}|${(rCg?.anchors ?? []).join(',')}|${av.history.join(',')}`;
    if (sig !== lastSig) {
