      returnLadder.push({ atMs: Date.now() - ret0, beat: rSt?.beat ?? null, objectiveId: rSt?.objectiveId ?? null,
        markerLabel: rSt?.markerLabel ?? null, world: worldRead(rSt), firedAnchors: rCg?.anchors ?? null,
